<template><view><view v-for="m in modules" :key="m.id" :style="{marginBottom:(m.setting.margin||0)+'rpx'}"><template v-if="m.type==='cube'"><view v-for="(c,i) in m.content" :key="i" class="cube" :style="{height:(m.setting.height||c.height)+'rpx'}"><MediaVideo v-if="c.type==='video'" :src="c.video" :poster="c.image" :loop="c.loop"/><image v-else :src="media(c.image)" mode="scaleToFill" @click="go(c)" :aria-label="m.title"/></view></template><PostGrid v-else-if="m.type==='post'" :posts="m.content" :articles="m.setting.style==='l'"/><view v-else-if="m.type==='nav'" class="nav"><view v-for="c in m.content" :key="c.title" @click="go(c)"><image :src="media(c.icon)"/><text>{{c.title}}</text></view></view></view></view></template>
<script setup>import {go,media} from '../lib/content';import MediaVideo from './MediaVideo.vue';import PostGrid from './PostGrid.vue';defineProps({modules:{type:Array,default:()=>[]}})</script>
<style scoped>.cube{width:100%}.cube image,.cube video{width:100%;height:100%;display:block}.nav{display:flex;padding:35rpx 0}.nav>view{flex:1;display:flex;flex-direction:column;align-items:center;gap:15rpx;font-size:24rpx}.nav image{width:54rpx;height:54rpx}</style>
